      || !validStatus.has(entry.status)
      || (entry.blocking !== null && typeof entry.blocking !== 'boolean')
      || !Array.isArray(entry.codes)) {
      throw new Error(`managed reviewer: invalid canonical report snapshot entry for ${command}`);
    }
